@font-face {
    font-family: "MyVariableFont";
    src: url("MyVariableFont.woff2") format("woff2-variations");
    font-weight: 100 900; /* Define the range of the weight axis */
    font-stretch: 75% 125%; /* Define the range of the width axis */
    font-style: oblique 0deg 20deg; /* Define the range of the slant axis */
}

body {
    font-family: "MyVariableFont", sans-serif;
}

.heading-large {
    font-variation-settings: "wght" 800, "wdth" 125, "slnt" 10;
    /* "wght" for weight, "wdth" for width, "slnt" for slant */
    /* Custom axes might be "GRAD" or "XTRA" etc. */
}

.responsive-text {
    font-variation-settings: "wght" 400; /* Default weight */
}

@media (min-width: 768px) {
    .responsive-text {
        font-variation-settings: "wght" 600, "wdth" 100;
    }
}

.animated-text:hover {
    transition: font-variation-settings 0.3s ease-in-out;
    font-variation-settings: "wght" 900, "wdth" 120;
}
